import AppKit

/// The About mini page (menu: "About DiskLED-plus"). The same page as
/// NeverSleep's and dotbar's: the app icon, the version, the PayPal donation
/// QR (paypal-qr.png in Resources, generated by scripts/make-qr.swift; bundle
/// copy done in make-app.sh), the license and the GitHub repo. Plain AppKit
/// NSWindow — no SwiftUI, matching the rest of the app. Cached so reopening
/// always shows the same window.
final class AboutWindowController: NSObject {
    static let shared = AboutWindowController()
    private var window: NSWindow?

    func show() {
        if window == nil {
            window = buildWindow()
        }
        NSApp.activate(ignoringOtherApps: true)
        window?.center()
        window?.makeKeyAndOrderFront(nil)
    }

    // MARK: - Page construction

    private func buildWindow() -> NSWindow {
        let version = Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String ?? "?"
        let build = Bundle.main.infoDictionary?["CFBundleVersion"] as? String ?? "?"

        func label(_ string: String, _ size: CGFloat, _ weight: NSFont.Weight = .regular,
                   _ color: NSColor = .labelColor) -> NSTextField {
            let l = NSTextField(labelWithString: string)
            l.font = .systemFont(ofSize: size, weight: weight)
            l.textColor = color
            l.alignment = .center
            return l
        }

        func link(_ text: String, _ url: URL, _ size: CGFloat) -> NSTextField {
            let l = NSTextField(labelWithAttributedString: NSAttributedString(
                string: text,
                attributes: [.link: url, .font: NSFont.systemFont(ofSize: size),
                             .foregroundColor: NSColor.linkColor]))
            l.isSelectable = true
            l.alignment = .center
            return l
        }

        func divider() -> NSBox {
            let box = NSBox()
            box.boxType = .separator
            box.widthAnchor.constraint(equalToConstant: 260).isActive = true
            return box
        }

        // App icon (96 pt) — the icns from Resources; the bare binary gets
        // macOS's generic icon instead, same as before the bundled app.
        let icon = NSImageView(image: NSApp.applicationIconImage)
        icon.widthAnchor.constraint(equalToConstant: 96).isActive = true
        icon.heightAnchor.constraint(equalToConstant: 96).isActive = true

        // Donation block: PayPal.me QR + tappable link (phones can't scan
        // their own screen, so the link matters). QR is bundled as
        // paypal-qr.png; when absent (bare `swift build`, no bundle) the
        // block degrades to text.
        let qrImage = Bundle.main.url(forResource: "paypal-qr", withExtension: "png")
            .flatMap { NSImage(contentsOf: $0) }
        var qrView: NSImageView?
        if let qrImage {
            let v = NSImageView(image: qrImage)
            v.imageScaling = .scaleProportionallyUpOrDown
            v.widthAnchor.constraint(equalToConstant: 88).isActive = true
            v.heightAnchor.constraint(equalToConstant: 88).isActive = true
            v.setAccessibilityLabel("PayPal donation QR code")
            qrView = v
        }

        let tagline = label(
            "Disk activity, shown the way hardware used to do it: one LED per channel, "
            + "blinking for every single tick of I/O — 33 times per second, nothing "
            + "averaged, nothing rounded up, nothing smoothed away.",
            11, .regular, .secondaryLabelColor)
        tagline.lineBreakMode = .byWordWrapping
        tagline.preferredMaxLayoutWidth = 252

        var views: [NSView] = [
            icon,
            label("DiskLED-plus", 22, .bold),
            label("Version \(version) (build \(build))", 11, .regular, .secondaryLabelColor),
            divider(),
        ]
        if let qrView { views.append(qrView) }
        views.append(contentsOf: [
            label("Support DiskLED-plus", 13, .semibold),
            link("paypal.me/MarcoDalmoro", URL(string: "https://paypal.me/MarcoDalmoro")!, 11),
            label("Point your phone's camera at the code — or click the link.", 10,
                  .regular, .secondaryLabelColor),
            divider(),
            label("© 2026 Marcus1571", 13),
            label("MIT", 11, .regular, .secondaryLabelColor),
            link("github.com/Marcus1571/diskled-plus",
                 URL(string: "https://github.com/Marcus1571/diskled-plus")!, 13),
            tagline,
        ])

        let stack = NSStackView(views: views)
        stack.orientation = .vertical
        stack.spacing = 10
        stack.alignment = .centerX
        stack.edgeInsets = NSEdgeInsets(top: 24, left: 24, bottom: 24, right: 24)

        let w = NSWindow(contentRect: NSRect(x: 0, y: 0, width: 300, height: stack.fittingSize.height),
                         styleMask: [.titled, .closable], backing: .buffered, defer: false)
        w.title = "About DiskLED-plus"
        w.isReleasedWhenClosed = false
        w.contentView = stack
        return w
    }
}
